          itemLayout="vertical"
          dataSource={rooms}
          renderItem={(item, index) => (
            <RoomListItem
              room={item.room}
              handleOpenChat={() => addChatBox(index)}
              handleOpenFileShare={() => addFileShare(index)}
            />
          )}
        />
      </Scroll>
      <Modal
        title="创建新的会议"
        open={open}
        okText="创建"
